#!/usr/bin/env node
// Deterministic shared dataset for the side-by-side comparison.
// Both products are loaded from these same files, so "find one record among 100,000" and
// "import 5,000 rows" are measured on identical data.
//
//   node gauntlet/compare/data/generate.mjs [--out <dir>] [--force]
//
// Output (default gauntlet/compare/data/out/, not committed; regenerated byte-for-byte):
//   contacts.csv              100,000 contacts (organisations and people)
//   contacts-import-5000.csv  5,000 new contacts for the import task (none exist in contacts.csv)
//   users.csv                 100,000 users
//   rates.csv                 100,000 exchange rates (50 currencies x 2,000 days, AED base)
//   needles.json              the records tasks look for (a contact, a user), and the expected row counts
//   manifest.json             generator version and SHA-256 of every file
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';
import { FIRST, LAST, BIZ_A, BIZ_B, SUFFIX, EMIRATES, COUNTRIES, TAGS, CURRENCIES } from './names.mjs';

export const GENERATOR_VERSION = 3;
export const COUNTS = Object.freeze({ contacts: 100_000, import: 5_000, users: 100_000, rates: 100_000 });
const here = path.dirname(fileURLToPath(import.meta.url));
export const DEFAULT_OUT = path.join(here, 'out');

// The record "find one record among 100,000" looks for. Its full name occurs exactly once in
// every generated file put together; the generator rerolls any other row that would collide.
export const NEEDLE = Object.freeze({
  index: 73_519,
  first: ['Shamma', 'شمة'], father: ['Waleed', 'وليد'], last: ['Al Romaithi', 'الرميثي'],
  parentIndex: 12_007,
});

/** mulberry32: small, fast, deterministic PRNG. */
export function rng(seed) {
  let a = seed >>> 0;
  const next = () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  return {
    next,
    int: (lo, hi) => lo + Math.floor(next() * (hi - lo + 1)),
    pick: arr => arr[Math.floor(next() * arr.length)],
    chance: p => next() < p,
    weighted: pairs => { let r = next(); for (const [v, w] of pairs) { if ((r -= w) < 0) return v; } return pairs[pairs.length - 1][0]; },
  };
}

export function csvCell(v) {
  const s = v === null || v === undefined ? '' : String(v);
  return /[",\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
}
const csvRow = cells => cells.map(csvCell).join(',') + '\n';
const pad = (n, w) => String(n).padStart(w, '0');
const slug = s => s.toLowerCase().replace(/[^a-z0-9]+/g, '.').replace(/^\.|\.$/g, '');
const needleName = `${NEEDLE.first[0]} ${NEEDLE.father[0]} ${NEEDLE.last[0]}`;
const needleNameAr = `${NEEDLE.first[1]} ${NEEDLE.father[1]} ${NEEDLE.last[1]}`;

const COUNTRY_NAMES = { AE: 'United Arab Emirates', SA: 'Saudi Arabia', OM: 'Oman', IN: 'India', GB: 'United Kingdom', CN: 'China' };
const FOREIGN_CITIES = { SA: ['Riyadh', 'Jeddah', 'Dammam'], OM: ['Muscat', 'Sohar', 'Salalah'], IN: ['Mumbai', 'Kochi', 'Chennai'], GB: ['London', 'Manchester'], CN: ['Shanghai', 'Shenzhen', 'Yiwu'] };
const cityOf = (r, country, em) => country === 'AE' ? em.name[0] : r.pick(FOREIGN_CITIES[country]);

function personName(r) {
  for (;;) {
    const f = r.pick(FIRST), m = r.pick(FIRST), l = r.pick(LAST);
    const en = `${f[0]} ${m[0]} ${l[0]}`;
    if (en === needleName) continue;
    return { en, ar: `${f[1]} ${m[1]} ${l[1]}`, first: f[0], last: l[0] };
  }
}
function companyName(r) {
  const a = r.pick(BIZ_A), b = r.pick(BIZ_B), s = r.pick(SUFFIX);
  return { en: `${a[0]} ${b[0]} ${s[0]}`, ar: `${s[1] === 'مؤسسة' || s[1] === 'شركة' ? s[1] + ' ' : ''}${a[1]} ${b[1]}${s[1] === 'مؤسسة' || s[1] === 'شركة' ? '' : ' ' + s[1]}` };
}
function uaePhone(r, mobile) {
  return mobile ? `+971 5${r.pick([0, 2, 4, 5, 6, 8])} ${r.int(100, 999)} ${pad(r.int(0, 9999), 4)}`
                : `+971 ${r.pick([2, 3, 4, 6, 7, 9])} ${r.int(200, 899)} ${pad(r.int(0, 9999), 4)}`;
}

function contactRows() {
  const r = rng(20261002);
  const rows = [];
  const companies = [];
  for (let i = 1; i <= COUNTS.contacts; i++) {
    const ref = `C${pad(i, 6)}`;
    const em = r.pick(EMIRATES);
    const country = r.weighted(COUNTRIES);
    const isNeedle = i === NEEDLE.index;
    const isCompany = !isNeedle && (i === NEEDLE.parentIndex || i <= 30 || r.chance(0.3));
    const row = {
      ref, kind: isCompany ? 'company' : 'person', name: '', name_ar: '', parent_ref: '', email: '', phone: '', mobile: '',
      street: `${r.int(1, 120)} ${r.pick(['Street', 'Road', 'Avenue'])} ${r.int(1, 40)}`, area: country === 'AE' ? r.pick(em.areas) : '', city: cityOf(r, country, em),
      emirate_code: country === 'AE' ? em.code : '', po_box: r.chance(0.6) ? String(r.int(1000, 99999)) : '', country_code: country,
      website: '', trade_licence: '', trn: '', tags: '', currency: 'AED', credit_limit: '',
    };
    if (isCompany) {
      const n = companyName(r);
      row.name = n.en; row.name_ar = n.ar;
      const dom = `${slug(n.en.split(' ').slice(0, 2).join(' ')).replace(/\./g, '')}${i}.example`;
      row.email = `info@${dom}`; row.website = `https://www.${dom}`; row.phone = uaePhone(r, false);
      row.trade_licence = String(r.int(100000, 999999));
      row.trn = r.chance(0.8) ? `100${pad(r.int(0, 999999999999), 12)}` : '';
      row.credit_limit = `${r.int(0, 500) * 1000}.00`;
      row.tags = [r.pick(TAGS), r.chance(0.3) ? r.pick(TAGS) : null].filter((t, k, a) => t && a.indexOf(t) === k).join(';');
      companies.push(ref);
    } else {
      const n = isNeedle ? { en: needleName, ar: needleNameAr, first: NEEDLE.first[0], last: NEEDLE.last[0] } : personName(r);
      row.name = n.en; row.name_ar = n.ar;
      row.email = `${slug(n.first)}.${slug(n.last)}.${i}@mail.example`;
      row.mobile = uaePhone(r, true);
      if (isNeedle) row.parent_ref = `C${pad(NEEDLE.parentIndex, 6)}`;
      else if (companies.length && r.chance(0.6)) row.parent_ref = companies[r.int(Math.max(0, companies.length - 400), companies.length - 1)];
      if (r.chance(0.2)) row.tags = r.pick(TAGS);
    }
    rows.push(row);
  }
  return rows;
}


function importRows() {
  // A file a user would bring from another system: plain headers, no internal references.
  const r = rng(5000);
  const rows = [];
  for (let i = 1; i <= COUNTS.import; i++) {
    const company = r.chance(0.35);
    const em = r.pick(EMIRATES);
    const country = r.weighted(COUNTRIES);
    let name, email;
    if (company) { const n = companyName(r); name = `${n.en} ${pad(i, 4)}`; email = `accounts${i}@import-${slug(n.en.split(' ')[0])}.example`; }
    else { const n = personName(r); name = n.en; email = `${slug(n.first)}.${slug(n.last)}.imp${i}@mail.example`; }
    rows.push({ Name: name, Email: email, Phone: uaePhone(r, !company), Street: `${r.int(1, 120)} Street ${r.int(1, 40)}`, City: cityOf(r, country, em), Country: COUNTRY_NAMES[country] });
  }
  return rows;
}

function userRows() {
  const r = rng(424242);
  const rows = [];
  for (let i = 1; i <= COUNTS.users; i++) {
    const n = personName(r);
    rows.push({ ref: `U${pad(i, 6)}`, name: n.en, name_ar: n.ar, login: `${slug(n.first)}.${slug(n.last)}.${pad(i, 6)}@staff.example`, lang: r.chance(0.3) ? 'ar' : 'en' });
  }
  return rows;
}

function rateRows() {
  // 50 currencies x 2,000 consecutive days ending 2026-09-30. AED per one unit of the currency, 6 decimals.
  const r = rng(3672500);
  const days = COUNTS.rates / CURRENCIES.length;
  const end = Date.UTC(2026, 8, 30);
  const rows = [];
  for (const [code, base] of CURRENCIES) {
    let v = base;
    for (let d = days - 1; d >= 0; d--) {
      v = base * (1 + (v / base - 1) * 0.98 + (r.next() - 0.5) * 0.004);
      const date = new Date(end - d * 86_400_000).toISOString().slice(0, 10);
      rows.push({ currency: code, date, rate: (code === 'USD' ? 3.6725 : v).toFixed(6) });
    }
  }
  return rows;
}

function writeCsv(file, rows, columns) {
  const parts = [csvRow(columns)];
  for (const row of rows) parts.push(csvRow(columns.map(c => row[c])));
  const text = parts.join('');
  fs.writeFileSync(file, text);
  return crypto.createHash('sha256').update(text).digest('hex');
}

export function generate({ out = DEFAULT_OUT, force = false } = {}) {
  const manifestFile = path.join(out, 'manifest.json');
  if (!force && fs.existsSync(manifestFile)) {
    const m = JSON.parse(fs.readFileSync(manifestFile, 'utf8'));
    const intact = m.version === GENERATOR_VERSION && Object.entries(m.files).every(([f, sha]) => {
      const p = path.join(out, f);
      return fs.existsSync(p) && crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex') === sha;
    });
    if (intact) return m;
  }
  fs.mkdirSync(out, { recursive: true });
  const contacts = contactRows();
  const imports = importRows();
  const users = userRows();
  const rates = rateRows();
  const allNames = [...contacts.map(c => c.name), ...imports.map(c => c.Name), ...users.map(u => u.name)];
  const needleHits = allNames.filter(n => n === needleName).length;
  if (needleHits !== 1) throw new Error(`needle name must occur exactly once, found ${needleHits}`);
  const contactNames = new Set(contacts.map(c => c.name));
  if (imports.some(i => contactNames.has(i.Name) && i.Name.match(/\d{4}$/))) throw new Error('import file overlaps the contact list');
  // The user "find one user among 100,000" and the API task look for: the first user from row
  // 68,311 on whose name occurs exactly once across every list (users.csv itself is unchanged).
  const nameCounts = new Map();
  for (const n of allNames) nameCounts.set(n, (nameCounts.get(n) || 0) + 1);
  const userNeedle = users.slice(68_310).find(u => nameCounts.get(u.name) === 1);
  if (!userNeedle) throw new Error('no user with a unique name for the user needle');
  const needle = contacts[NEEDLE.index - 1];
  const parent = contacts[NEEDLE.parentIndex - 1];
  const files = {
    'contacts.csv': writeCsv(path.join(out, 'contacts.csv'), contacts, Object.keys(contacts[0])),
    'contacts-import-5000.csv': writeCsv(path.join(out, 'contacts-import-5000.csv'), imports, Object.keys(imports[0])),
    'users.csv': writeCsv(path.join(out, 'users.csv'), users, Object.keys(users[0])),
    'rates.csv': writeCsv(path.join(out, 'rates.csv'), rates, Object.keys(rates[0])),
  };
  const needles = {
    contact: { ref: needle.ref, name: needle.name, name_ar: needle.name_ar, email: needle.email, mobile: needle.mobile, parent_ref: parent.ref, parent_name: parent.name },
    user: { ref: userNeedle.ref, name: userNeedle.name, name_ar: userNeedle.name_ar, login: userNeedle.login, lang: userNeedle.lang },
    import: { rows: imports.length, first: imports[0].Name, last: imports[imports.length - 1].Name },
    counts: { contacts: contacts.length, companies: contacts.filter(c => c.kind === 'company').length, users: users.length, rates: rates.length },
  };
  fs.writeFileSync(path.join(out, 'needles.json'), JSON.stringify(needles, null, 2) + '\n');
  files['needles.json'] = crypto.createHash('sha256').update(fs.readFileSync(path.join(out, 'needles.json'))).digest('hex');
  const manifest = { version: GENERATOR_VERSION, files };
  fs.writeFileSync(manifestFile, JSON.stringify(manifest, null, 2) + '\n');
  return manifest;
}

export function loadNeedles(out = DEFAULT_OUT) {
  generate({ out });
  return JSON.parse(fs.readFileSync(path.join(out, 'needles.json'), 'utf8'));
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const args = process.argv.slice(2);
  const outIdx = args.indexOf('--out');
  const out = outIdx >= 0 ? path.resolve(args[outIdx + 1]) : DEFAULT_OUT;
  const t0 = Date.now();
  const m = generate({ out, force: args.includes('--force') });
  console.log(`dataset v${m.version} in ${out} (${Date.now() - t0} ms)`);
  for (const [f, sha] of Object.entries(m.files)) console.log(`  ${f}  ${sha.slice(0, 16)}`);
}
